'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={characters:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 5v2"/>',timeline:'<path d="M12 3v18M5 6h7M12 12h7M5 18h7"/><circle cx="4" cy="6" r="2"/><circle cx="20" cy="12" r="2"/><circle cx="4" cy="18" r="2"/>',places:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 0 1 14 0Z"/><circle cx="12" cy="10" r="2.5"/>',relations:'<circle cx="12" cy="5" r="3"/><circle cx="4" cy="19" r="3"/><circle cx="20" cy="19" r="3"/><path d="m10 8-4 8M14 8l4 8M7 19h10"/>',chapters:'<path d="M12 5c-3-3-7-3-10-1v16c3-2 7-2 10 1 3-3 7-3 10-1V4c-3-2-7-2-10 1ZM12 5v16"/>',notes:'<path d="M4 3h12l4 4v14H4ZM16 3v5h4M8 12h8M8 16h5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',link:'<path d="m10 13 4-4M8 15l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 9l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',arrow:'<path d="m14 6-6 6 6 6M8 12h12"/>'};
function icon(name){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.notes}</svg>`}
const pages=[['characters','الشخصيات'],['timeline','التسلسل الزمني'],['places','أماكن القصة'],['relations','شبكة العلاقات'],['chapters','الفصول والكتابة'],['notes','دفتر الأفكار']];
function createBlankWorld(name='',description='',settings){return{id:uid(),world:{name,description},settings:settings?structuredClone(settings):{theme:'sand',background:'',opacity:35,blur:12,glass:55},characters:[],events:[],places:[],relations:[],chapters:[],notes:[],trash:[],isDemo:false}}
let data=createBlankWorld();
let current='characters',filter='الكل',query='',chosenCharacter='',characterMode='board';
function nav(){ $('#nav').innerHTML=pages.map(([id,label])=>`<button data-page="${id}" class="nav-item ${current===id?'active':''}">${icon(id)}<span>${label}</span><span class="nav-count">${(data[id==='timeline'?'events':id]||[]).length}</span></button>`).join('');$('#worldName').textContent=data.world.name||'أنشئ عالمك';$('#crumbWorld').textContent=data.world.name||'حكايتك';$('#crumbPage').textContent=pages.find(p=>p[0]===current)[1];$('#worldAvatar').textContent=data.world.name.slice(0,1)||'+'}
function heading(title,subtitle,addLabel){return `<div class="page-heading"><div><div class="eyebrow">قصتك، عالمك</div><h1>${title}</h1><p>${subtitle}</p></div>${addLabel?`<button class="button primary" id="addButton">${icon('plus')}${addLabel}</button>`:''}</div>`}
function render(){nav();$('#main').className='fade-in';if(!library.worlds.length)return renderWelcome();({characters:renderCharacters,timeline:renderTimeline,places:renderPlaces,relations:renderRelations,chapters:renderChapters,notes:renderNotes})[current]();}
function renderCharacterCards(){let chars=data.characters.filter(c=>(filter==='الكل'||filter==='المفضلة'&&c.favorite||c.role===filter)&&[c.name,c.subtitle,c.tags,c.description].join(' ').includes(query));$('#main').innerHTML=heading('شخصياتك','وجوه تحمل الحكاية، وأسرار تمنحها الحياة.','شخصية جديدة')+`<section class="inspiration"><div><div class="small-tag">✦ من دفتر الحكاية</div><h2>كل حكاية تبدأ بشخصية.</h2><p>امنحها اسمًا، واكتب عنها بطريقتك.</p></div><svg class="inspiration-art" viewBox="0 0 400 240" fill="none"><path d="M10 190Q130 40 280 180T430 20M-20 210Q120 60 300 200T420 35" stroke="#a98d5b" stroke-width=".7" opacity=".35"/><circle cx="205" cy="126" r="57" stroke="#bd9f6c" stroke-width=".6"/><circle cx="205" cy="126" r="74" stroke="#bd9f6c" stroke-width=".6" stroke-dasharray="3 7"/><path d="m180 151 24-77 26 77-26-13Z" stroke="#a58654" stroke-width="1"/><path d="M205 74v111m-41-59h82" stroke="#a58654" stroke-width=".6"/><circle cx="90" cy="120" r="4" fill="#E78B48" opacity=".6"/><circle cx="314" cy="166" r="5" fill="#102E50" opacity=".4"/><path d="m325 80 4 9 9 3-9 3-4 9-3-9-9-3 9-3Z" fill="#F5C45E"/></svg></section><div class="mini-stats"><div class="mini-stat"><strong>${data.characters.length.toLocaleString('ar')}</strong> شخصية في عالمك</div><div class="mini-stat"><i></i><strong>${data.relations.length.toLocaleString('ar')}</strong> علاقات تربطها</div><div class="mini-stat"><strong>${data.characters.filter(c=>c.favorite).length.toLocaleString('ar')}</strong> شخصيات مفضلة</div></div><div class="toolbar"><div class="filters">${['الكل','بطلة','شخصية رئيسية','خصم','المفضلة'].map(f=>`<button class="filter ${f===filter?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div><label class="search-wrap">${icon('search')}<input id="search" placeholder="ابحث عن شخصية…" aria-label="البحث في الشخصيات" value="${esc(query)}"></label></div><div class="character-grid">${chars.map(c=>`<article class="character-card" tabindex="0" role="button" data-character="${c.id}" aria-label="فتح بطاقة ${esc(c.name)}"><div class="portrait">${characterArt(c)}<span class="card-category">${esc(c.role)}</span><button class="star-button ${c.favorite?'is-star':''}" data-star="${c.id}" aria-label="${c.favorite?'إزالة من':'إضافة إلى'} المفضلة">${c.favorite?'★':'☆'}</button></div><div class="card-body"><div class="card-title-row"><h3>${esc(c.name)}</h3><span style="color:#a69873">↗</span></div><div class="card-subtitle">${esc(c.subtitle)}</div><p>${esc(c.description)}</p><div class="card-tags">${c.tags.split(/[،,]/).filter(Boolean).slice(0,3).map(t=>`<span class="tag">${esc(t.trim())}</span>`).join('')}</div><div class="card-foot"><span>${icon('relations')}${data.relations.filter(r=>r.from===c.id||r.to===c.id).length} علاقات</span><span>استكشف الشخصية ${icon('arrow')}</span></div></div></article>`).join('')}<button class="card-add" id="cardAdd"><span class="plus">+</span>هناك شخصية تنتظر حكايتها<small>أضف وجهًا جديدًا إلى عالمك</small></button></div>`;}
$('#nav').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b){current=b.dataset.page;query='';filter='الكل';render()}});
$('#main').addEventListener('click',e=>{let f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;renderCharacters()} });
$('#main').addEventListener('input',e=>{if(e.target.id==='search'){let pos=e.target.selectionStart;query=e.target.value;renderCharacters();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
let library={schemaVersion:1,active:'',worlds:[]},db=null,saveQueue=Promise.resolve(),saveTimer,toastTimer,selectedChapter='';
function uid(){return typeof crypto!=='undefined'&&crypto.randomUUID?crypto.randomUUID():'id'+Date.now()+Math.random().toString(16).slice(2)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200)}
async function openDB(){return new Promise((resolve,reject)=>{let req=indexedDB.open('sard-local-v1',1);req.onupgradeneeded=()=>req.result.createObjectStore('state');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function initialize(){let stored;try{db=await openDB();stored=await new Promise((resolve,reject)=>{let r=db.transaction('state').objectStore('state').get('library');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}catch(e){try{stored=JSON.parse(localStorage.getItem('sard-library')||'null')}catch(e){}}if(stored){try{library=validateLibrary(stored);data=library.worlds.find(w=>w.id===library.active)||library.worlds[0]||createBlankWorld()}catch(e){toast('تعذّر قراءة الحفظ السابق. يمكنك استيراد نسختك الاحتياطية.')}}let migrated=removeExamples(library)||!!stored?.worlds?.some(w=>w.mapDocument||w.mapImage);data=library.worlds.find(w=>w.id===library.active)||library.worlds[0]||createBlankWorld();for(const w of library.worlds){for(const c of w.characters)migrated=normalizeCharacter(c)||migrated;for(const t of w.trash)if(t.collection==='characters')migrated=normalizeCharacter(t.record)||migrated;}applySettings();selectedChapter=data.chapters[0]?.id||'';render();if(!stored||migrated)save();navigator.storage?.persist?.().catch(()=>{});}
function save(){library.active=library.worlds.some(w=>w.id===data.id)?data.id:'';$('#savedBadge').textContent='… جارٍ الحفظ';$('#saveState').textContent='جارٍ حفظ آخر تعديل';const snapshot=JSON.stringify(library);saveQueue=saveQueue.catch(()=>{}).then(async()=>{try{if(db){await new Promise((resolve,reject)=>{const tx=db.transaction('state','readwrite');tx.objectStore('state').put(JSON.parse(snapshot),'library');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}else localStorage.setItem('sard-library',snapshot);$('#savedBadge').textContent='✓ محفوظ محليًا';$('#saveState').textContent='الحفظ التلقائي مفعّل';return true}catch(e){$('#savedBadge').textContent='⚠ لم يُحفظ';$('#saveState').textContent='صدّر نسخة لحفظ آخر تعديل';toast('تعذّر الحفظ المحلي. احفظ نسخة احتياطية الآن.');return false}});return saveQueue}
function field(label,name,value='',type='text',required=false){return `<div class="field"><label for="f-${name}">${label}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${required?'required':''}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='text'?'maxlength="500"':''}>`}</div>`}
function selectField(label,name,values,value='',optional=false){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${optional?'<option value="">دون تحديد</option>':''}${values.map(v=>{let [id,text]=Array.isArray(v)?v:[v,v];return `<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`}).join('')}</select></div>`}
function modal(title,body,onSubmit,remove){$('#modal').classList.remove('character-edit-modal');$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;$('#modalFooter').innerHTML=`${remove?'<button type="button" class="button danger" id="deleteItem">نقل إلى المحذوفات</button>':''}<button type="submit" class="button primary">حفظ التغييرات</button><button type="button" class="button" id="cancelModal">إلغاء</button>`;$('#modalForm').onsubmit=async e=>{e.preventDefault();const b=$('#modalForm').querySelector('[type=submit]');b.disabled=true;try{const result=await onSubmit(Object.fromEntries(new FormData(e.target)));if(result!==false){$('#modal').close();render();await save();toast('تم حفظ التغييرات')}}catch(e){toast(e.message||'تعذّر الحفظ. حاول مرة أخرى.')}finally{b.disabled=false}};$('#cancelModal').onclick=()=>$('#modal').close();if(remove)$('#deleteItem').onclick=()=>{remove();$('#modal').close();render();save();toast('نُقل إلى المحذوفات — يمكنك استعادته من الإعدادات')};$('#modal').showModal();}
function moveToTrash(collection,id){const record=data[collection].find(c=>c.id===id);if(!record)return;let linked={};if(collection==='characters'){linked.relations=data.relations.filter(r=>r.from===id||r.to===id);data.relations=data.relations.filter(r=>r.from!==id&&r.to!==id)}data.trash.push({id:uid(),collection,record:structuredClone(record),linked,deletedAt:Date.now()});data[collection]=data[collection].filter(c=>c.id!==id);}
function normalizeCharacter(c){if(c.freeformVersion===1)return false;const old=[c.desire,c.fear,c.secret].filter(Boolean);c.description=[c.description,...old].filter(Boolean).join('\n\n');c.desire=c.fear=c.secret='';c.aliases=c.aliases||'';c.properties=c.properties||[];for(const [key,name] of [['subtitle','اللقب'],['age','العمر'],['tags','السمات'],['role','التصنيف']])if(c[key]&&!c.properties.some(p=>p.name===name))c.properties.push({name,value:c[key]});c.freeformVersion=1;return true;}
function editorCharacter(id){const existing=data.characters.find(c=>c.id===id);const c=existing?structuredClone(existing):{id:uid(),name:'',role:'',subtitle:'',age:'',description:'',desire:'',fear:'',secret:'',tags:'',portrait:data.characters.length%5,favorite:false,aliases:'',properties:[],freeformVersion:1};normalizeCharacter(c);let image=c.image||'',propertyIndex=0;
modal(id?'تعديل الشخصية':'شخصية جديدة',`<div class="free-character-top"><div class="free-character-details"><input class="character-name-input" name="name" id="characterName" aria-label="اسم الشخصية" placeholder="اسم الشخصية" maxlength="500" value="${esc(c.name)}" required><div class="alias-line"><span>أسماء أخرى</span><input name="aliases" aria-label="أسماء أخرى" placeholder="أضف اسمًا آخر…" value="${esc(c.aliases)}" maxlength="500"></div><div id="freeProperties"></div><button type="button" class="add-free-property" id="addFreeProperty">+ إضافة خاصية</button></div><div class="free-character-media"><label for="characterImage" class="free-image-pick" id="freeImagePick">${image?`<img src="${esc(image)}" alt="صورة الشخصية">`:id?characterArt(c):'<span>إضافة صورة<small>من جهازك · اختياري</small></span>'}</label><input id="characterImage" type="file" accept="image/png,image/jpeg,image/webp" hidden><button type="button" class="remove-free-image" id="removeFreeImage">إزالة الصورة</button></div></div><div class="free-biography"><div class="free-text-label"><button type="button" id="focusBiography">نص</button><span>اكتب بطريقتك</span></div><textarea name="description" id="freeBiography" aria-label="نبذة الشخصية" placeholder="اكتب عن الشخصية…" spellcheck="false">${esc(c.description)}</textarea></div>`,async f=>{const name=f.name.trim();if(!name)throw new Error('اكتب اسم الشخصية');const properties=[...$('#freeProperties').querySelectorAll('.free-property-row')].map(row=>({name:row.querySelector('[data-property-name]').value.trim(),value:row.querySelector('[data-property-value]').value})).filter(p=>p.name||p.value);if(properties.some(p=>!p.name))throw new Error('أضف اسمًا للخاصية أو احذفها');if(properties.length>100)throw new Error('الحد الأقصى 100 خاصية');Object.assign(c,{name,aliases:f.aliases,description:f.description,image,properties,freeformVersion:1});for(const [key,label] of [['subtitle','اللقب'],['age','العمر'],['tags','السمات'],['role','التصنيف']])c[key]=properties.find(p=>p.name===label)?.value||'';if(id)Object.assign(existing,c);else data.characters.push(c);chosenCharacter=c.id;},id?()=>moveToTrash('characters',id):null);
$('#modal').classList.add('character-edit-modal');const addProperty=(p={name:'',value:''})=>{if($('#freeProperties').children.length>=100)return toast('الحد الأقصى 100 خاصية');const i=propertyIndex++;const row=document.createElement('div');row.className='free-property-row';row.innerHTML=`<input data-property-name aria-label="اسم الخاصية ${i+1}" placeholder="اسم الخاصية" maxlength="200" value="${esc(p.name)}"><input data-property-value aria-label="قيمة الخاصية ${i+1}" placeholder="القيمة" maxlength="100000" value="${esc(p.value)}"><button type="button" aria-label="حذف الخاصية ${i+1}">×</button>`;row.querySelector('button').onclick=()=>row.remove();$('#freeProperties').append(row);return row;};c.properties.forEach(addProperty);$('#addFreeProperty').onclick=()=>addProperty()?.querySelector('input').focus();$('#focusBiography').onclick=()=>$('#freeBiography').focus();$('#characterImage').onchange=async e=>{try{if(!e.target.files[0])return;image=await imageFile(e.target.files[0]);$('#freeImagePick').innerHTML=`<img src="${esc(image)}" alt="صورة الشخصية">`;$('#removeFreeImage').hidden=false;}catch(err){toast(err.message)}finally{e.target.value=''}};$('#removeFreeImage').hidden=!image&&!(id&&c.id==='c1'&&!c.hideDefaultArt);$('#removeFreeImage').onclick=()=>{image='';c.hideDefaultArt=true;$('#freeImagePick').innerHTML='<span>إضافة صورة<small>من جهازك · اختياري</small></span>';$('#removeFreeImage').hidden=true;};$('#characterName').focus();}
function editorEvent(id){let c=data.events.find(c=>c.id===id)||{id:uid(),title:'',date:String(data.events.length+1),era:'',description:'',character:'',place:'',chapter:''};modal(id?'تفاصيل الحدث':'حدث جديد',`${field('اسم الحدث','title',c.title,'text',true)}<div class="field-row">${field('ترتيبه في الزمن','date',c.date,'number',true)}${field('التاريخ أو الحقبة','era',c.era,'text',true)}</div>${field('ماذا حدث؟','description',c.description,'textarea')}<div class="field-row">${selectField('الشخصية المحورية','character',data.characters.map(c=>[c.id,c.name]),c.character,true)}${selectField('المكان','place',data.places.map(p=>[p.id,p.name]),c.place,true)}</div>${selectField('الفصل المرتبط','chapter',data.chapters.map(h=>[h.id,h.title]),c.chapter,true)}`,f=>{f.title=f.title.trim();if(!f.title||!Number.isFinite(Number(f.date)))throw new Error('أدخل عنوانًا وترتيبًا صحيحًا');Object.assign(c,f);if(!id)data.events.push(c)},id?()=>moveToTrash('events',id):null)}
function editorPlace(id){let p=data.places.find(p=>p.id===id)||{id:uid(),name:'',type:'مدينة',description:''};modal(id?'تفاصيل '+p.name:'مكان جديد',`${field('اسم المكان','name',p.name,'text',true)}${selectField('نوع المكان','type',['مدينة','ميناء','منطقة','مبنى','طريق','أخرى'],p.type)}${field('وصف المكان وأهميته','description',p.description,'textarea')}`,f=>{f.name=f.name.trim();if(!f.name)throw new Error('اكتب اسم المكان');Object.assign(p,f);if(!id)data.places.push(p)},id?()=>moveToTrash('places',id):null)}
function editorRelation(id){if(data.characters.length<2)return toast('أضف شخصيتين أولًا لبناء علاقة');let r=data.relations.find(r=>r.id===id)||{id:uid(),from:data.characters[0].id,to:data.characters[1].id,type:'حليف',description:''};modal(id?'تفاصيل العلاقة':'خيط جديد في الحكاية',`<div class="field-row">${selectField('الشخصية الأولى','from',data.characters.map(c=>[c.id,c.name]),r.from)}${selectField('الشخصية الثانية','to',data.characters.map(c=>[c.id,c.name]),r.to)}</div>${selectField('نوع العلاقة','type',['حليف','صداقة','عداوة','عائلة','حب','سر مشترك','أخرى'],r.type)}${field('ما الذي يربطهما؟','description',r.description,'textarea')}`,f=>{if(f.from===f.to)throw new Error('اختر شخصيتين مختلفتين');if(data.relations.some(t=>t.id!==r.id&&((t.from===f.from&&t.to===f.to)||(t.to===f.from&&t.from===f.to))&&t.type===f.type))throw new Error('هذه العلاقة موجودة بالفعل');Object.assign(r,f);if(!id)data.relations.push(r)},id?()=>moveToTrash('relations',id):null)}
function editorChapter(id){let h=data.chapters.find(h=>h.id===id)||{id:uid(),title:'',status:'مسودة',content:''};modal(id?'إعدادات الفصل':'فصل جديد',`${field('عنوان الفصل','title',h.title,'text',true)}${selectField('حالة الفصل','status',['فكرة','مسودة','مراجعة','مكتمل'],h.status)}`,f=>{if(!f.title.trim())throw new Error('اكتب عنوان الفصل');Object.assign(h,f);if(!id)data.chapters.push(h);selectedChapter=h.id},id?()=>moveToTrash('chapters',id):null)}
function editorNote(id){let n=data.notes.find(n=>n.id===id)||{id:uid(),title:'',kind:'فكرة',content:''};modal(id?'من دفتر الأفكار':'فكرة جديدة',`${field('عنوان الفكرة','title',n.title,'text',true)}${selectField('التصنيف','kind',['فكرة','قانون العالم','سؤال مفتوح','تفصيلة','بحث'],n.kind)}${field('لا تدع الفكرة تفلت','content',n.content,'textarea')}`,f=>{if(!f.title.trim())throw new Error('اكتب عنوان الفكرة');Object.assign(n,f);if(!id)data.notes.push(n)},id?()=>moveToTrash('notes',id):null)}
async function imageFile(file){if(!/^image\/(png|jpeg|webp)$/.test(file.type))throw new Error('اختر صورة PNG أو JPG أو WebP');if(file.size>8*1024*1024)throw new Error('اختر صورة أصغر من 8 ميجابايت');return new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('تعذّر قراءة الصورة'));reader.readAsDataURL(file)})}
$('#closeModal').onclick=()=>$('#modal').close();$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){let r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#main').addEventListener('click',e=>{let star=e.target.closest('[data-star]');if(star){let c=data.characters.find(c=>c.id===star.dataset.star);c.favorite=!c.favorite;save();renderCharacters();return}let card=e.target.closest('[data-character]');if(card){editorCharacter(card.dataset.character);if(card.classList.contains('add-free-property'))$('#addFreeProperty').click();return}if(e.target.closest('#addButton,#cardAdd'))({characters:editorCharacter,timeline:editorEvent,places:editorPlace,relations:editorRelation,chapters:editorChapter,notes:editorNote})[current]();let ev=e.target.closest('[data-event]');if(ev)editorEvent(ev.dataset.event);let p=e.target.closest('[data-place-edit]');if(p)editorPlace(p.dataset.placeEdit);let r=e.target.closest('[data-relation]');if(r)editorRelation(r.dataset.relation);let n=e.target.closest('[data-note]');if(n)editorNote(n.dataset.note);});
$('#main').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.character-card')){e.preventDefault();editorCharacter(e.target.dataset.character)}});
function characterArt(c){return c.image?`<img src="${esc(c.image)}" alt="${esc(c.name)}">`:`<div class="blank-character-art"><span>${esc(c.name?.slice(0,1)||'')}</span></div>`}
function renderCharacters(){if(characterMode==='cards'){renderCharacterCards();$('#main').insertAdjacentHTML('afterbegin','<button class="button view-return" data-mode="board">↗ العودة إلى مساحة الشخصية</button>');return}let c=data.characters.find(c=>c.id===chosenCharacter)||data.characters[0];chosenCharacter=c?.id||'';$('#main').innerHTML=heading('وجوه الحكاية','كل شخصية، عالم ينتظر أن يُكتشف.','شخصية جديدة')+`<div class="studio-toolbar"><div class="section-tabs"><button class="active" data-mode="board">${icon('characters')} مساحة الشخصية</button><button data-mode="cards">▦ البطاقات</button></div><span class="scene-caption">${data.isDemo?'عالم تجريبي · أنشئ عالمك من القائمة العلوية':'عالمك الخاص'} <i></i> ${data.characters.length} شخصيات</span></div><section class="character-studio"><div class="document-list glass"><label class="search-wrap">${icon('search')}<input id="boardSearch" placeholder="ابحث عن شخصية…" value="${esc(query)}"></label><div class="document-list-label">شخصيات العالم <span>${data.characters.length}</span></div>${data.characters.filter(c=>[c.name,c.tags].join(' ').includes(query)).map(t=>`<button class="document-item ${t.id===c?.id?'selected':''}" data-select-character="${t.id}"><span class="tiny-portrait">${characterArt(t)}</span><span>${esc(t.name)}<small>${esc(t.subtitle)}</small></span>${t.favorite?'<b>✦</b>':''}</button>`).join('')}<button class="document-add" id="cardAdd">+ أضف شخصية</button></div><div class="character-stage">${c?`<article class="character-document glass"><header class="document-header"><div class="doc-crumb">${icon('characters')} بطاقة شخصية <span>·</span> ${esc(data.world.name)}</div><button class="button compact" data-character="${c.id}">↗ تعديل البطاقة</button></header><div class="document-content"><div class="character-info"><h2>${esc(c.name)}</h2>${c.aliases?`<div class="document-aliases">${esc(c.aliases)}</div>`:''}<div class="custom-character-properties">${(c.properties||[]).map(p=>`<div class="custom-character-property"><span>${esc(p.name)}</span><p>${esc(p.value)}</p></div>`).join('')}</div><button class="add-free-property" data-character="${c.id}">+ إضافة خاصية</button><p class="character-description free-description">${esc(c.description)||'اكتب عن الشخصية بطريقتك…'}</p>${data.relations.some(r=>r.from===c.id||r.to===c.id)?`<div class="document-links"><small>العلاقات</small>${data.relations.filter(r=>r.from===c.id||r.to===c.id).map(r=>{let other=data.characters.find(t=>t.id===(r.from===c.id?r.to:r.from));return other?`<button data-relation="${r.id}" class="connection-chip ${r.type==='عداوة'?'enemy':''}">${esc(other.name)}<span>${esc(r.type)}</span></button>`:''}).join('')}</div>`:''}</div><div class="character-large-image">${characterArt(c)}<div class="portrait-caption"><span>من عالم ${esc(data.world.name)}</span><b>${esc(c.subtitle)}</b></div></div></div><footer class="document-foot"><span>✦ كل تفصيلة تمنحها حياة</span><button data-star="${c.id}">${c.favorite?'★ من المفضلة':'☆ أضف للمفضلة'}</button></footer></article><div class="floating-caption"><span class="local-dot"></span>كل ما تكتبه يبقى هنا، على جهازك.</div>`:empty('عالمك ينتظر أول شخصية','ابدأ باسم، ودع الحكاية تتشكل.','شخصية جديدة')}</div></section>`;}
function empty(title,description,button){return `<div class="empty glass"><span>✦</span><h2>${title}</h2><p>${description}</p>${button?`<button class="button primary" id="addButton">+ ${button}</button>`:''}</div>`}
function renderTimeline(){let events=[...data.events].sort((a,b)=>Number(a.date)-Number(b.date));$('#main').innerHTML=heading('التسلسل الزمني','الأحداث كما وقعت، والخيوط كما تتقاطع.','حدث جديد')+`<div class="studio-toolbar"><span class="scene-caption">${events.length} أحداث · مرتبة بحسب تسلسل الحكاية</span><label class="search-wrap">${icon('search')}<input id="eventSearch" placeholder="ابحث عن حدث…" value="${esc(query)}"></label></div><div class="timeline-layout"><section class="timeline-track">${events.filter(e=>[e.title,e.era,e.description].join(' ').includes(query)).map((e,i)=>`<article class="timeline-event glass"><div class="time-dot"></div><div class="event-era"><span>${esc(e.era)}</span><b>${String(i+1).padStart(2,'0')}</b></div><button class="event-title" data-event="${e.id}">${esc(e.title)} ↗</button><p>${esc(e.description)}</p><div class="event-tags">${[[e.character,'characters','name'],[e.place,'places','name'],[e.chapter,'chapters','title']].map(([id,col,key])=>{let t=data[col].find(t=>t.id===id);return t?`<span class="tag">${esc(t[key])}</span>`:''}).join('')}</div></article>`).join('')||empty('كل حكاية لها بداية','أضف الأحداث واربطها بالشخصيات والأماكن.','حدث جديد')}</section><aside class="story-side glass"><small>نظرة على التسلسل</small><h3>خيط يمتد عبر حكايتك</h3><p>يمكنك استخدام تواريخ واقعية أو حقب من عالمك. رقم الترتيب يحدد تسلسل الحدث في الحكاية.</p><div class="side-number">${events.length}<span>أحداث</span></div><div class="side-number">${new Set(events.map(e=>e.character).filter(Boolean)).size}<span>شخصيات محورية</span></div><div class="side-number">${new Set(events.map(e=>e.place).filter(Boolean)).size}<span>أماكن في الحكاية</span></div></aside></div>`;}
function renderPlaces(){$('#main').innerHTML=heading('أماكن القصة','الأماكن التي تحتفظ بذكريات حكايتك.','مكان جديد')+`<div class="studio-toolbar"><span class="scene-caption">${data.places.length} أماكن في عالمك</span></div><div class="places-directory">${data.places.map(p=>`<button class="place-entry glass" data-place-edit="${p.id}"><span class="role-chip">${esc(p.type)}</span><h2>${esc(p.name)}</h2><p>${esc(p.description)||'أضف نبذة عن المكان…'}</p><small>${data.events.filter(e=>e.place===p.id).length} أحداث مرتبطة · تعديل التفاصيل ↗</small></button>`).join('')||empty('مكان تنتظره الحكاية','اكتب اسم المكان ونبذته، واربطه بالأحداث.','مكان جديد')}</div>`;}
function relationColor(type){return type==='عداوة'?'#BE3D2A':type==='حب'?'#E78B48':type==='سر مشترك'?'#9f8fab':'#F5C45E'}
function graphPosition(c,i,total){if(c.graphX!==undefined)return{x:c.graphX,y:c.graphY};if(total===1)return{x:50,y:50};let a=2*Math.PI*i/total-Math.PI/2;return{x:50+33*Math.cos(a),y:50+32*Math.sin(a)}}
function renderRelations(){const positions=new Map(data.characters.map((c,i)=>[c.id,graphPosition(c,i,data.characters.length)]));$('#main').innerHTML=heading('شبكة العلاقات','كل خط بين شخصيتين، حكاية أخرى.','علاقة جديدة')+`<div class="studio-toolbar"><span class="scene-caption">اسحب الشخصيات لترتيب الشبكة · اضغط اسم الرابط لتعديل العلاقة</span><div class="legend"><span><i style="background:#F5C45E"></i> روابط</span><span><i style="background:#BE3D2A"></i> عداوة</span><button class="button compact" id="resetGraph">⌖ ترتيب تلقائي</button></div></div><div class="relationship-canvas glass" id="graphCanvas"><svg class="graph-lines" viewBox="0 0 100 100" preserveAspectRatio="none">${data.relations.map(r=>{let a=positions.get(r.from),b=positions.get(r.to);return a&&b?`<line data-line="${r.id}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${relationColor(r.type)}" vector-effect="non-scaling-stroke"/>`:''}).join('')}</svg>${data.relations.map(r=>{let a=positions.get(r.from),b=positions.get(r.to);return a&&b?`<button class="relation-label" data-relation="${r.id}" data-rel-label="${r.id}" style="left:${(a.x+b.x)/2}%;top:${(a.y+b.y)/2}%;--rel-color:${relationColor(r.type)}">${esc(r.type)}</button>`:''}).join('')}${data.characters.map(c=>{let p=positions.get(c.id);return `<button class="graph-node" data-node="${c.id}" style="left:${p.x}%;top:${p.y}%"><span class="node-picture">${characterArt(c)}</span><span><b>${esc(c.name)}</b><small>${esc(c.subtitle)}</small></span></button>`}).join('')}<span class="canvas-note">${data.characters.length} شخصيات <i></i> ${data.relations.length} روابط</span></div><div class="relation-list">${data.relations.map(r=>`<button class="relation-row glass" data-relation="${r.id}"><span class="relation-dot" style="background:${relationColor(r.type)}"></span><b>${esc(data.characters.find(c=>c.id===r.from)?.name||'شخصية محذوفة')}</b><span>↔</span><b>${esc(data.characters.find(c=>c.id===r.to)?.name||'شخصية محذوفة')}</b><small>${esc(r.type)}</small><p>${esc(r.description)}</p></button>`).join('')}</div>`;bindGraph(positions);}
function bindGraph(positions){let drag;const canvas=$('#graphCanvas');canvas.addEventListener('pointerdown',e=>{let node=e.target.closest('[data-node]');if(!node)return;drag={node,id:node.dataset.node,x:e.clientX,y:e.clientY,moved:false};node.setPointerCapture(e.pointerId)});canvas.addEventListener('pointermove',e=>{if(!drag)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5)drag.moved=true;if(!drag.moved)return;const box=canvas.getBoundingClientRect(),c=data.characters.find(c=>c.id===drag.id);c.graphX=Math.max(10,Math.min(90,(e.clientX-box.left)/box.width*100));c.graphY=Math.max(10,Math.min(90,(e.clientY-box.top)/box.height*100));positions.set(c.id,{x:c.graphX,y:c.graphY});drag.node.style.left=c.graphX+'%';drag.node.style.top=c.graphY+'%';for(const r of data.relations){let a=positions.get(r.from),b=positions.get(r.to),line=canvas.querySelector(`[data-line="${r.id}"]`),label=canvas.querySelector(`[data-rel-label="${r.id}"]`);if(line&&a&&b){for(let [k,v] of Object.entries({x1:a.x,y1:a.y,x2:b.x,y2:b.y}))line.setAttribute(k,v);label.style.left=(a.x+b.x)/2+'%';label.style.top=(a.y+b.y)/2+'%'}}});canvas.addEventListener('pointerup',()=>{if(!drag)return;const id=drag.id,moved=drag.moved;drag=null;if(moved)save();else{chosenCharacter=id;current='characters';characterMode='board';render()}});canvas.addEventListener('pointercancel',()=>{if(drag?.moved)save();drag=null});$('#resetGraph').onclick=()=>{data.characters.forEach(c=>{delete c.graphX;delete c.graphY});save();renderRelations()};}
function wordCount(text){return text.trim()?text.trim().split(/\s+/u).length:0}
function renderChapters(){let h=data.chapters.find(h=>h.id===selectedChapter)||data.chapters[0];selectedChapter=h?.id||'';$('#main').innerHTML=heading('بين السطور','اترك للعالم مساحة، ولحكايتك صوتًا.','فصل جديد')+`<div class="studio-toolbar"><span class="scene-caption">${data.chapters.length} فصول · ${data.chapters.reduce((n,h)=>n+wordCount(h.content),0).toLocaleString('ar')} كلمات</span><button class="button compact" id="exportText">↓ تصدير المخطوط</button></div><div class="writing-layout"><aside class="chapter-list glass"><h3>المخطوط</h3>${data.chapters.map((t,i)=>`<button class="chapter-item ${t.id===h?.id?'selected':''}" data-chapter-select="${t.id}"><span>${String(i+1).padStart(2,'0')}</span><div><b>${esc(t.title)}</b><small>${esc(t.status)} · ${wordCount(t.content)} كلمات</small></div></button>`).join('')}<button class="document-add" id="addButton">+ فصل جديد</button></aside>${h?`<section class="writing-editor glass"><header><div><span class="role-chip">${esc(h.status)}</span><h2>${esc(h.title)}</h2></div><button id="editChapter" class="icon-button" aria-label="إعدادات الفصل">⋯</button></header><textarea id="chapterContent" aria-label="نص الفصل" placeholder="ابدأ بجملة. الباقي سيأتي…" spellcheck="false">${esc(h.content)}</textarea><footer><span id="wordCount">${wordCount(h.content)} كلمات</span><span>الحفظ تلقائي أثناء الكتابة</span><button class="button compact" id="focusMode">⛶ وضع التركيز</button></footer></section>`:empty('صفحة تنتظر صوتك','أضف فصلًا لتبدأ الكتابة.','فصل جديد')}</div>`;if(h){$('#chapterContent').oninput=e=>{h.content=e.target.value;$('#wordCount').textContent=wordCount(h.content)+' كلمات';clearTimeout(saveTimer);saveTimer=setTimeout(save,350)};$('#editChapter').onclick=()=>editorChapter(h.id);$('#focusMode').onclick=()=>{document.body.classList.toggle('focus-writing');$('#focusMode').textContent=document.body.classList.contains('focus-writing')?'⛶ خروج من التركيز':'⛶ وضع التركيز'};}$('#exportText').onclick=()=>download(data.chapters.map(h=>h.title+'\n\n'+h.content).join('\n\n────────\n\n'),data.world.name+' — المخطوط.txt','text/plain;charset=utf-8');}
function renderNotes(){$('#main').innerHTML=heading('أفكار على الهامش','البذور الصغيرة التي قد تصبح حكاية.','فكرة جديدة')+`<div class="studio-toolbar"><div class="filters">${['الكل','فكرة','قانون العالم','سؤال مفتوح','تفصيلة','بحث'].map(f=>`<button class="filter ${filter===f?'active':''}" data-note-filter="${f}">${f}</button>`).join('')}</div></div><div class="notes-grid">${data.notes.filter(n=>filter==='الكل'||n.kind===filter).map((n,i)=>`<button class="note-card glass note-${i%3}" data-note="${n.id}"><span class="note-kind">${esc(n.kind)}</span><h3>${esc(n.title)}</h3><p>${esc(n.content)}</p><span class="note-edit">↗ أكمل الفكرة</span></button>`).join('')||empty('احتفظ بالشرارة','فكرة، سؤال، أو تفصيلة تستحق أن تبقى.','فكرة جديدة')}</div>`;}
$('#main').addEventListener('click',e=>{let mode=e.target.closest('[data-mode]');if(mode){characterMode=mode.dataset.mode;renderCharacters()}let c=e.target.closest('[data-select-character]');if(c){chosenCharacter=c.dataset.selectCharacter;renderCharacters()}let h=e.target.closest('[data-chapter-select]');if(h){selectedChapter=h.dataset.chapterSelect;renderChapters()}let f=e.target.closest('[data-note-filter]');if(f){filter=f.dataset.noteFilter;renderNotes()}});
$('#main').addEventListener('input',e=>{if(['boardSearch','eventSearch'].includes(e.target.id)){const id=e.target.id,pos=e.target.selectionStart;query=e.target.value;current==='characters'?renderCharacters():renderTimeline();$('#'+id).focus();$('#'+id).setSelectionRange(pos,pos)}});
const themes={sand:'radial-gradient(ellipse at 85% 12%,#E78B4855,transparent 48%),radial-gradient(ellipse at 10% 88%,#F5C45E38,transparent 45%),linear-gradient(135deg,#102E50,#303b32 49%,#171d23)',night:'radial-gradient(ellipse at 20% 30%,#294f7755,transparent 60%),radial-gradient(ellipse at 85% 75%,#E78B4820,transparent 50%),linear-gradient(135deg,#102E50,#071726)',ember:'radial-gradient(ellipse at 80% 20%,#BE3D2A50,transparent 50%),radial-gradient(ellipse at 10% 85%,#E78B4838,transparent 55%),linear-gradient(125deg,#102E50,#2b251e)'};
function applySettings(){const s=data.settings;$('#background').style.backgroundImage=s.background?`url("${s.background}")`:(themes[s.theme]||themes.sand);$('#background').style.filter=`blur(${s.background?Number(s.blur||0):0}px)`;$('#background').style.transform=s.background&&s.blur?'scale(1.08)':'none';document.documentElement.style.setProperty('--bg-shade',String(Number(s.opacity||0)/100));document.documentElement.style.setProperty('--glass-alpha',String(Number(s.glass??55)/100));}
function openSettings(){modal('مساحتك، كما تحبها',`<p class="muted">اختر جو الحكاية، أو ضع خلفيتك الخاصة من جهازك.</p><div class="theme-options">${[['sand','الرمل والذهب'],['night','ليل الحكاية'],['ember','الجمر']].map(([id,text])=>`<button class="theme-option" type="button" data-theme="${id}"><i style="background:${themes[id]}"></i>${text}</button>`).join('')}</div><div class="field"><label for="backgroundUpload">خلفية من جهازك</label><input id="backgroundUpload" type="file" accept="image/png,image/jpeg,image/webp"></div><label class="check-label"><input type="checkbox" name="removeBackground"> إزالة الخلفية المرفوعة</label><div class="field" style="margin-top:20px"><label for="shadeRange">تعتيم الخلفية</label><input id="shadeRange" name="opacity" type="range" min="0" max="80" value="${data.settings.opacity??35}"></div><div class="field"><label for="blurRange">ضبابية الصورة</label><input id="blurRange" name="blur" type="range" min="0" max="45" value="${data.settings.blur??12}"></div><div class="field"><label for="glassRange">كثافة الزجاج</label><input id="glassRange" name="glass" type="range" min="15" max="90" value="${data.settings.glass??55}"></div><input type="hidden" name="theme" id="themeInput" value="${esc(data.settings.theme)}"><div class="setting-section"><h3>قصتك، على جهازك</h3><p>الحفظ تلقائي داخل هذا المتصفح. النسخة الاحتياطية ملف على جهازك، وتشمل العوالم والصور والفصول. لا توجد مزامنة سحابية.</p><div class="settings-actions"><button type="button" class="button compact" id="settingsExport">↓ حفظ نسخة في ملف</button><button type="button" class="button compact" id="settingsImport">↑ استيراد نسخة</button></div></div><div class="setting-section"><h3>المحذوفات (${data.trash.length})</h3>${data.trash.map(t=>`<div class="trash-item"><span>${esc(t.record.name||t.record.title||t.record.type)}</span><button type="button" class="button compact" data-restore="${t.id}">استعادة</button></div>`).join('')||'<p>لا توجد عناصر محذوفة.</p>'}</div>`,async f=>{let background=data.settings.background;if(f.removeBackground)background='';if($('#backgroundUpload').files[0])background=await imageFile($('#backgroundUpload').files[0]);data.settings={theme:f.theme,opacity:Number(f.opacity),blur:Number(f.blur),glass:Number(f.glass),background};applySettings()});$('#modalBody').querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{$('#themeInput').value=b.dataset.theme;$('#modalBody').querySelectorAll('[data-theme]').forEach(t=>t.style.borderColor=t===b?'#E78B48':'#f5c45e30')});$('#settingsExport').onclick=exportBackup;$('#settingsImport').onclick=()=>$('#importInput').click();$('#modalBody').querySelectorAll('[data-restore]').forEach(b=>b.onclick=async()=>{const t=data.trash.find(t=>t.id===b.dataset.restore);if(!t)return;if(t.collection==='relations'&&(!data.characters.some(c=>c.id===t.record.from)||!data.characters.some(c=>c.id===t.record.to)))return toast('استعد الشخصيتين المرتبطتين أولًا');if(!data[t.collection].some(r=>r.id===t.record.id))data[t.collection].push(t.record);if(t.linked?.relations)for(let r of t.linked.relations){if(!data.relations.some(t=>t.id===r.id)&&data.characters.some(c=>c.id===r.from)&&data.characters.some(c=>c.id===r.to))data.relations.push(r)}data.trash=data.trash.filter(x=>x.id!==t.id);await save();$('#modal').close();render();openSettings();toast('تمت استعادة العنصر')});}
function openWorlds(){if(!library.worlds.length)return startStory();modal('عوالمك',`<div class="world-list">${library.worlds.map(w=>`<button type="button" class="world-row ${w.id===data.id?'active':''}" data-world="${w.id}"><b>${esc(w.world.name)}</b><small>${w.characters.length} شخصيات${w.isDemo?' · عالم تجريبي':''}</small></button>`).join('')}</div>${field('اسم العالم الحالي','name',data.world.name,'text',true)}${field('نبذة العالم','description',data.world.description,'textarea')}<div class="setting-section"><button type="button" class="button" id="newWorld">+ عالم جديد فارغ</button><p class="muted">يمكنك التنقل بين العوالم دون فقد أي تفاصيل.</p></div>`,f=>{if(!f.name.trim())throw new Error('اكتب اسم العالم');data.world.name=f.name.trim();data.world.description=f.description});$('#modalBody').querySelectorAll('[data-world]').forEach(b=>b.onclick=()=>{data=library.worlds.find(w=>w.id===b.dataset.world);library.active=data.id;selectedChapter=data.chapters[0]?.id||'';chosenCharacter=data.characters[0]?.id||'';query='';filter='الكل';applySettings();$('#modal').close();save();render()});$('#newWorld').onclick=()=>{$('#modal').close();modal('حكاية جديدة',`${field('اسم العالم','name','','text',true)}${field('بذرة الحكاية','description','','textarea')}`,f=>{if(!f.name.trim())throw new Error('اكتب اسم العالم');data={id:uid(),world:{name:f.name.trim(),description:f.description},settings:structuredClone(data.settings),characters:[],events:[],places:[],relations:[],chapters:[],notes:[],trash:[],isDemo:false};library.worlds.push(data);current='characters';selectedChapter='';chosenCharacter='';applySettings()})};}
function download(content,name,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\uFEFF',content],{type}));a.href=url;a.download=name.replace(/[\\/:*?"<>|]/g,'-');document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('تم تجهيز الملف للحفظ على جهازك');}
async function exportBackup(){clearTimeout(saveTimer);await save();const json=JSON.stringify({app:'sard',schemaVersion:1,exportedAt:new Date().toISOString(),library},null,2);download(json,'sard-backup-'+new Date().toISOString().slice(0,10)+'.json','application/json');}
function validateLibrary(input){if(!input||input.schemaVersion!==1||!Array.isArray(input.worlds)||input.worlds.length>100)throw new Error('هذا ليس ملف سَرد مدعومًا');const string=(v,limit=1000000)=>{if(v===undefined||v===null)return '';if(typeof v!=='string'||v.length>limit)throw new Error('نص غير صالح في الملف');return v};const id=v=>{if(typeof v!=='string'||!(/^[a-zA-Z0-9_-]{1,120}$/).test(v))throw new Error('معرّف غير صالح في الملف');return v};const image=v=>{if(!v)return '';if(typeof v!=='string'||v.length>12000000||!/^data:image\/(png|jpeg|webp);base64,[a-zA-Z0-9+/=]+$/.test(v))throw new Error('صورة غير صالحة في الملف');return v};const num=(v,min,max,fallback)=>{if(v===undefined)return fallback;v=Number(v);if(!Number.isFinite(v)||v<min||v>max)throw new Error('قيمة رقمية غير صالحة');return v};const schemas={characters:['name','role','subtitle','age','description','desire','fear','secret','tags'],events:['title','date','era','description','character','place','chapter'],places:['name','type','description'],relations:['from','to','type','description'],chapters:['title','status','content'],notes:['title','kind','content']};function record(col,r){if(!r||typeof r!=='object')throw new Error('عنصر غير صالح');let o={id:id(r.id)};for(let k of schemas[col])o[k]=string(r[k]);if(col==='characters'){o.portrait=num(r.portrait,0,4,0);o.favorite=!!r.favorite;o.image=image(r.image);o.hideDefaultArt=!!r.hideDefaultArt;o.aliases=string(r.aliases,500);o.freeformVersion=r.freeformVersion===1?1:0;if(r.properties!==undefined&&(!Array.isArray(r.properties)||r.properties.length>100))throw new Error('خصائص غير صالحة');o.properties=(r.properties||[]).map(p=>{if(!p||typeof p!=='object')throw new Error('خاصية غير صالحة');const name=string(p.name,200).trim();if(!name)throw new Error('اسم خاصية فارغ');return{name,value:string(p.value,100000)}});normalizeCharacter(o);if(r.graphX!==undefined){o.graphX=num(r.graphX,0,100,50);o.graphY=num(r.graphY,0,100,50)}}if(col==='places'){o.x=num(r.x,0,100,50);o.y=num(r.y,0,100,50)}if(col==='events'&&!Number.isFinite(Number(o.date)))throw new Error('ترتيب حدث غير صالح');if(['name','title'].some(k=>k in o&&!o[k].trim()))throw new Error('عنوان فارغ في الملف');if(col==='relations'&&(o.from===o.to||!o.from||!o.to))throw new Error('علاقة غير صالحة');return o}
const worlds=input.worlds.map(w=>{if(!w?.world?.name||!w.settings)throw new Error('بيانات عالم غير صالحة');let o={id:id(w.id),world:{name:string(w.world.name,500),description:string(w.world.description)},settings:{theme:themes[w.settings.theme]?w.settings.theme:'sand',background:image(w.settings.background),opacity:num(w.settings.opacity,0,80,35),blur:num(w.settings.blur,0,45,12),glass:num(w.settings.glass,15,90,55)},isDemo:!!w.isDemo,trash:[]};if(w.mapArchive)o.mapArchive=string(w.mapArchive,65*1024*1024);else if(w.mapDocument||w.mapImage)o.mapArchive=string(JSON.stringify({document:w.mapDocument||null,image:w.mapImage||''}),65*1024*1024);for(let col of Object.keys(schemas)){if(!Array.isArray(w[col])||w[col].length>20000)throw new Error('قائمة غير صالحة');o[col]=w[col].map(r=>record(col,r));if(new Set(o[col].map(r=>r.id)).size!==o[col].length)throw new Error('معرّفات مكررة')}if(w.trash){if(!Array.isArray(w.trash)||w.trash.length>20000)throw new Error('محذوفات غير صالحة');o.trash=w.trash.map(t=>{if(!schemas[t.collection])throw new Error('محذوفات غير صالحة');return{id:id(t.id),collection:t.collection,record:record(t.collection,t.record),linked:{relations:(t.linked?.relations||[]).map(r=>record('relations',r))},deletedAt:num(t.deletedAt,0,1e15,Date.now())}})}return o});if(new Set(worlds.map(w=>w.id)).size!==worlds.length)throw new Error('عوالم مكررة');return{schemaVersion:1,active:worlds.some(w=>w.id===input.active)?input.active:worlds[0]?.id||'',worlds}}
$('#importInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;try{if(file.size>65*1024*1024)throw new Error('الملف أكبر من 65 ميجابايت');const parsed=JSON.parse((await file.text()).replace(/^\uFEFF/,''));if(parsed.app!=='sard'||parsed.schemaVersion!==1)throw new Error('اختر ملف نسخة احتياطية من سَرد');const incoming=validateLibrary(parsed.library);removeExamples(incoming);if(!incoming.worlds.length)throw new Error('هذه النسخة لا تحتوي على عوالم شخصية لاستيرادها');for(let w of incoming.worlds){w.id=uid();w.world.name+=' (مستورد)';library.worlds.push(w)}data=incoming.worlds[0];library.active=data.id;selectedChapter=data.chapters[0]?.id||'';chosenCharacter=data.characters[0]?.id||'';applySettings();$('#modal').close();render();await save();toast('تم الاستيراد كعوالم إضافية. عوالمك السابقة محفوظة.')}catch(e){toast(e.message||'تعذّر قراءة الملف. لم تتغيّر بياناتك.')}};
$('#settingsButton').onclick=openSettings;$('#mobileSettings').onclick=openSettings;$('#worldButton').onclick=openWorlds;$('#worldAvatar').onclick=openWorlds;$('#exportButton').onclick=exportBackup;
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.body.classList.remove('focus-writing');if((e.ctrlKey||e.metaKey)&&e.key==='s'){e.preventDefault();save().then(ok=>toast(ok?'تم حفظ عالمك على الجهاز':'احفظ نسخة احتياطية لحماية آخر تعديل'))}});window.addEventListener('pagehide',()=>{if(saveTimer){clearTimeout(saveTimer);save()}});document.addEventListener('visibilitychange',()=>{if(document.hidden){clearTimeout(saveTimer);save()}});
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort());for(const t of [{name:'read_story_outline',title:'قراءة مخطط القصة',description:'قراءة مخطط الحكاية المفتوحة على الجهاز دون تعديلها.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw new Error('هذه الأداة لا تحتاج بيانات إضافية');return{world:data.world.name,characters:data.characters.map(c=>({id:c.id,name:c.name})),events:data.events.map(e=>({title:e.title,era:e.era})),chapters:data.chapters.map(h=>({title:h.title,words:wordCount(h.content)}))}}},{name:'navigate_story_view',title:'فتح مساحة من الحكاية',description:'فتح قسم موجود من الحكاية دون إنشاء بيانات أو تعديلها.',inputSchema:{type:'object',properties:{view:{type:'string',enum:pages.map(p=>p[0])}},required:['view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='view')||!pages.some(p=>p[0]===input.view))throw new Error('القسم غير موجود');current=input.view;query='';filter='الكل';render();return{view:current}}}]){try{Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{})}catch(e){}}}
function removeExamples(lib){const before=lib.worlds.length;lib.worlds=lib.worlds.filter(w=>!w.isDemo&&w.id!=='demo');if(!lib.worlds.some(w=>w.id===lib.active))lib.active=lib.worlds[0]?.id||'';return before!==lib.worlds.length}
function renderWelcome(){$('#main').innerHTML=`<section class="welcome glass"><span class="welcome-mark">◈</span><div class="eyebrow">سَرد · نسخة ألفا</div><h1>حكايتك تبدأ هنا.</h1><p>ابدأ بعالم يحمل اسمك، ثم أضف شخصياتك وأحداثك وفصولك.<br>كل ما تكتبه يبقى على جهازك.</p><button class="button primary" id="startStory">+ ابدأ حكايتك</button><button class="button" id="welcomeImport">استيراد نسخة احتياطية</button></section>`;$('#startStory').onclick=startStory;$('#welcomeImport').onclick=()=>$('#importInput').click()}
function startStory(){modal('حكايتك الأولى',`${field('اسم العالم','name','','text',true)}${field('نبذة العالم','description','','textarea')}`,f=>{if(!f.name.trim())throw new Error('اكتب اسم عالمك');data=createBlankWorld(f.name.trim(),f.description,data.settings);library.worlds.push(data);library.active=data.id;current='characters';chosenCharacter='';selectedChapter=''})}
